-- Isolated staging only. Existing bigk tables are not changed.

-- Source: 20261029152350_bigk_private_commerce.sql
-- BigK private application schema. Run in Supabase SQL Editor as postgres.
-- Safe to re-run: existing products/stock/prices/orders are never overwritten.
BEGIN;
CREATE SCHEMA IF NOT EXISTS bigk_staging;
REVOKE ALL ON SCHEMA bigk_staging FROM PUBLIC;
SET LOCAL search_path = bigk_staging, pg_catalog;
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL,code TEXT NOT NULL,category TEXT NOT NULL,price_cents INTEGER CHECK(price_cents>=0),approved INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 0,featured INTEGER NOT NULL DEFAULT 0,images TEXT NOT NULL,tags TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0,position BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE IF NOT EXISTS variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),size TEXT NOT NULL,stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock),reported INTEGER,position BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,status TEXT NOT NULL,subtotal INTEGER NOT NULL,shipping INTEGER NOT NULL,total INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'eur',email TEXT NOT NULL,phone TEXT NOT NULL,customer TEXT NOT NULL,receipt_hash TEXT NOT NULL,request_key TEXT UNIQUE NOT NULL,request_hash TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,stripe_session TEXT UNIQUE,tracking TEXT);
CREATE TABLE IF NOT EXISTS order_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),variant_id TEXT NOT NULL REFERENCES variants(id),name TEXT NOT NULL,size TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0));
CREATE TABLE IF NOT EXISTS webhook_events(id TEXT PRIMARY KEY,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,action TEXT NOT NULL,entity TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_tokens(hash TEXT PRIMARY KEY,email TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customer_sessions(hash TEXT PRIMARY KEY,email TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_outbox(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),kind TEXT NOT NULL,email TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,lease_until BIGINT NOT NULL DEFAULT 0,sent_at TEXT,UNIQUE(order_id,kind));
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
ALTER TABLE variants ENABLE ROW LEVEL SECURITY;
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE order_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE webhook_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE rate_limits ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE login_tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE customer_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE email_outbox ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA bigk_staging FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA bigk_staging FROM PUBLIC;
DO $$
DECLARE role_name text;
BEGIN
  FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN
      EXECUTE format('REVOKE ALL ON SCHEMA bigk_staging FROM %I',role_name);
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA bigk_staging FROM %I',role_name);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA bigk_staging FROM %I',role_name);
    END IF;
  END LOOP;
END $$;
CREATE INDEX IF NOT EXISTS orders_email_created ON orders(email,created_at DESC);
CREATE INDEX IF NOT EXISTS orders_pending_expiry ON orders(expires_at) WHERE status='pending';
CREATE INDEX IF NOT EXISTS variants_product ON variants(product_id);
CREATE INDEX IF NOT EXISTS order_lines_order ON order_lines(order_id);
CREATE INDEX IF NOT EXISTS email_due ON email_outbox(next_attempt,lease_until) WHERE sent_at IS NULL;
