roducts/web/summit-resized-9-2626427.webp","/products/web/summit-resized-9-2626420.webp","/products/web/summit-resized-9-2626441.webp"]'),('P023','["/products/web/snake-scarf-black.webp"]'),('P024','["/products/web/snake-scarf-cream.webp"]'),('P025','["/products/web/snake-scarf-emerald.webp"]'),('P026','["/products/web/velvet-cream-front.webp","/products/web/velvet-cream-angle.webp","/products/web/velvet-cream-back.webp","/products/web/velvet-cream-detail.webp"]'),('P027','["/products/web/velvet-black-front.webp","/products/web/velvet-black-back-model.webp","/products/web/velvet-black-front-flat.webp","/products/web/velvet-black-angle.webp","/products/web/velvet-black-back-flat.webp"]')) AS v(id,images)
 WHERE p.id=v.id AND p.approved=0 AND p.active=0 AND p.images::jsonb IS DISTINCT FROM v.images::jsonb
 RETURNING p.id
), logged AS (
 INSERT INTO bigk_staging.audit(action,entity,created_at)
 SELECT 'catalog.web-images-synced',id,to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') FROM updated RETURNING entity
