CREATE TABLE IF NOT EXISTS bigk_staging.admin_returns(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES bigk_staging.orders(id),reference TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS admin_returns_order ON bigk_staging.admin_returns(order_id);

ALTER TABLE bigk_staging.product_content ENABLE ROW LEVEL SECURITY;
