INSERT INTO bigk_staging.product_content(product_id,content) SELECT 'P019','{"composition": "Outer fabric: 98% polyamide (nylon), 2% polyester. Filling: approximately 90% white goose down, according to the supplier; the remaining filling composition is not specified.", "care": "Wash at 30°C on a gentle cycle. Supplier’s detailed care note: wash inside out and separately; do not bleach, tumble dry or dry clean. Check the sewn-in care label.", "fit": "Regular fit is listed for S–2XL. Down filling weight by size: S 80 g, M 85 g, L 90 g, XL 95 g, 2XL 100 g, 3XL 105 g. These are filling weights, not the total weight of the jacket.", "details": "A lightweight padded men’s winter jacket with a black outer fabric, zip fastening and concealed zipped pockets. According to the supplier, the filling contains approximately 90% white goose down. The wind-resistant, water-repellent outer fabric helps protect against cold wind and light rain. Designed for everyday use and walking. Autumn/Winter 2026 collection. Water-repellent does not mean waterproof."}' WHERE EXISTS(SELECT 1 FROM bigk_staging.products WHERE id='P019') ON CONFLICT(product_id) DO NOTHING;

