-- Source: 20261030084046_bigk_durable_media.sql
-- Durable media for serverless hosting. Local/staging review first.

CREATE TABLE IF NOT EXISTS bigk_staging.media_assets(id TEXT PRIMARY KEY,metadata TEXT NOT NULL,original BYTEA NOT NULL,web BYTEA NOT NULL,original_bytes INTEGER NOT NULL CHECK(original_bytes>0),web_bytes INTEGER NOT NULL CHECK(web_bytes>0),created_at TEXT NOT NULL);

ALTER TABLE bigk_staging.media_assets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON bigk_staging.media_assets FROM PUBLIC,anon,authenticated;

-- Source: 20261030084941_bigk_withdrawal_requests.sql
-- Private customer withdrawal records; test on staging before remote application.

CREATE TABLE IF NOT EXISTS bigk_staging.withdrawal_requests(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES bigk_staging.orders(id),request_key TEXT NOT NULL,request_hash TEXT NOT NULL,snapshot TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested',created_at TEXT NOT NULL,resolved_at TEXT,resolution TEXT,UNIQUE(order_id,request_key));
CREATE INDEX IF NOT EXISTS withdrawal_order ON bigk_staging.withdrawal_requests(order_id,status);

ALTER TABLE bigk_staging.withdrawal_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON bigk_staging.withdrawal_requests FROM PUBLIC,anon,authenticated;

