UPDATE bigk_staging.products SET active=0,approved=0,tags=(tags::jsonb || '["alias:P012"]'::jsonb)::text,version=version+1 WHERE id='P013' AND NOT(tags::jsonb @> '["alias:P012"]'::jsonb);
